mapper.select:
SELECT a.target_table AS target_table, a.target_key AS target_key, a.action_type AS action_type, a.reason AS reason, a.actor_user_id AS actor_id, a.actor_name AS actor_name, a.occurred_at AS when FROM tb_audit_log a WHERE a.target_table IN ('tb_purchase_request','tb_stock_adjust','tb_inbound_correct') AND a.action_type IN ('APPROVE','REJECT','UPDATE')
AND a.actor_user_id = #{actorId}
ORDER BY a.occurred_at DESC LIMIT #{limit}
